using System;using System.IO;using System.Linq;using System.Collections.Generic;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;using Newtonsoft.Json.Linq;
public static class V10Import {
 const string Source="E:/personalProject/Demo3/demo6/아트/정수리-질감수정-v10";
 public static object Run(){if(!Application.dataPath.Contains("topdown-v10-review-isolated")||EditorApplication.isPlaying)throw new Exception("Owned isolated Edit only");Directory.CreateDirectory("Assets/ReviewV10/Before");AssetDatabase.Refresh();var rows=new List<object>();foreach(var p in JArray.Parse(File.ReadAllText(Source+"/runtime-manifest.json"))){string id=(string)p["id"];string file=((int)p["ppu"]==256?"Assets/Art/TopDownPilotV9/Hero/":"Assets/Resources/TopDownPilotV9/")+id+".png";string before="Assets/ReviewV10/Before/"+id+".png";if(!File.Exists(before)&&!AssetDatabase.CopyAsset(file,before))throw new Exception("Before backup failed "+file);File.Copy(Source+"/runtime-PNG/"+id+".png",file,true);AssetDatabase.ImportAsset(file,ImportAssetOptions.ForceSynchronousImport);var imp=(TextureImporter)AssetImporter.GetAtPath(file);if(id=="entry_floor"){imp.spritePixelsPerUnit=(float)p["ppu"];imp.SaveAndReimport();}var sp=AssetDatabase.LoadAssetAtPath<Sprite>(file);if(sp.rect.width!=(int)p["width"]||sp.rect.height!=(int)p["height"]||sp.pixelsPerUnit!=(float)p["ppu"])throw new Exception("Dimensions/PPU changed "+id);var old=AssetDatabase.LoadAssetAtPath<Sprite>(before);if(id!="entry_floor"&&old.pivot!=sp.pivot)throw new Exception("Pivot changed "+id);rows.Add(new{id,path=file,width=sp.rect.width,height=sp.rect.height,ppu=sp.pixelsPerUnit,pivot=sp.pivot.ToString(),filter=imp.filterMode.ToString(),mips=imp.mipmapEnabled});}EditorSceneManager.OpenScene("Assets/Scenes/DungeonTest.unity");File.WriteAllText(Source+"/import-validation.json",Newtonsoft.Json.JsonConvert.SerializeObject(rows,Newtonsoft.Json.Formatting.Indented));return rows;}
}
